import type { Encounter } from "../../../domain/types";

/**
 * Unique pixel-art banner per encounter, embedded as data URIs so there is no file that can go missing
 * (320x96 px each, drawn for this project; scale them with `image-rendering: pixelated`).
 */
export type EncounterTheme = "meadow" | "quarry" | "ruins" | "forest" | "summit";

export const THEME_ART: Record<EncounterTheme, string> = {
  meadow: "data:image/png;base64,",
  quarry: "data:image/png;base64,",
  ruins: "data:image/png;base64,",
  forest: "data:image/png;base64,",
  summit: "data:image/png;base64,",
};

/** Banner tone used by PageBanner for each theme. */
export const THEME_TONE = {
  meadow: "grass",
  quarry: "gold",
  ruins: "accent",
  forest: "grass",
  summit: "violet",
} as const;

const REGULAR_ORDER: EncounterTheme[] = ["meadow", "quarry", "ruins", "forest"];

/**
 * Picks the theme from the encounter order (1 = meadow, 2 = quarry, 3 = ruins, 4 = forest, final boss = summit).
 * TODO(gateway): use a theme/environment field from the backend once the encounter payload has one.
 */
export function encounterTheme(e: Pick<Encounter, "order" | "isFinalBoss">): EncounterTheme {
  return e.isFinalBoss ? "summit" : REGULAR_ORDER[(e.order - 1) % REGULAR_ORDER.length];
}

export const encounterArt = (e: Pick<Encounter, "order" | "isFinalBoss">): string => THEME_ART[encounterTheme(e)];
